const products = [
    { id: 1, name: "Jacket", price: 1999, category: "Men", image: "https://m.media-amazon.com/images/I/71li-ujtlUL._UY741_.jpg", rating: 4.5 },
    { id: 2, name: "Shoes", price: 1899, category: "Men", image: "https://m.media-amazon.com/images/I/61utX8kBDlL._UY695_.jpg", rating: 4.2 },
    { id: 3, name: "Dress", price: 3499, category: "Women", image: "data:image/jpeg;base64,", rating: 4.7 },
    { id: 4, name: "Handbag", price: 999, category: "Women", image: "https://encrypted-tbn0.gstatic.com/shopping?q=tbn:ANd9GcSl6FrwELf3BtprpxU28hZ3UU1PFHe7Kd391vKI1LzqVvznJwgzkfNcNU2nP3UUXjeLnNNxnCxDgpju7Dth_lQfavxewnW18b2RYu1r4OSb4sIHtsQAzkueHNLt", rating: 4.1 },
    { id: 5, name: "T-Shirt", price: 299, category: "Children", image: "data:image/jpeg;base64,", rating: 4.3 },
    { id: 6, name: "Shoes", price: 779, category: "Children", image: "https://assets.myntassets.com/dpr_1.5,q_30,w_400,c_limit,fl_progressive/assets/images/2025/FEBRUARY/12/l3ZzdGud_fa18395a34444c658367b4983cf1d9ea.jpg", rating: 4.0 },
    { id: 7, name: "Sweater", price: 899, category: "Men", image: "data:image/jpeg;base64,", rating: 4.6 },
    { id: 8, name: "Nauvari Sadi", price: 4899, category: "Women", image: "data:image/jpeg;base64,", rating: 4.4 },
    { id: 9, name: "Hoodie", price: 599, category: "Children", image: "https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcQhcSsHzlJLW8FaIlNnEbmfnJnaLVw-O1qUyQ&s", rating: 4.2 },
    { id: 10, name: "Kurti Set", price: 2499, category: "Women", image: "data:image/jpeg;base64,", rating: 4.9 },
    { id: 11, name: "Kurta Set", price: 1299, category: "Men", image: "data:image/jpeg;base64,", rating: 4.3 },
    { id: 12, name: "Cargo Jeans", price: 999, category: "Men", image: "data:image/jpeg;base64,", rating: 4.1 }
];

let cart = JSON.parse(localStorage.getItem("cart")) || [];
let currentCategory = "All";

/* ================= DISPLAY PRODUCTS ================= */

function displayProducts() {
    const productList = document.getElementById("productList");
    if (!productList) return;

    const searchInput = document.getElementById("searchInput");
    const searchValue = searchInput ? searchInput.value.toLowerCase() : "";

    productList.innerHTML = "";

    const filtered = products.filter(product =>
        (currentCategory === "All" || product.category === currentCategory) &&
        product.name.toLowerCase().includes(searchValue)
    );

    if (filtered.length === 0) {
        productList.innerHTML = `
            <div class="col-12 text-center">
                <h5>No products found 😢</h5>
            </div>
        `;
        return;
    }

    filtered.forEach(product => {

        // ⭐ Generate stars
        let stars = "";
        const fullStars = Math.floor(product.rating);
        const halfStar = product.rating % 1 !== 0;

        for (let i = 0; i < fullStars; i++) {
            stars += "⭐";
        }
        if (halfStar) {
            stars += "⭐";
        }

        // Check if product is in cart
        const cartItem = cart.find(item => item.id === product.id);
        const quantity = cartItem ? cartItem.quantity : 0;

        let buttonHtml;
        if (quantity > 0) {
            buttonHtml = `
                <div class="d-flex align-items-center justify-content-center">
                    <button class="btn btn-sm btn-outline-secondary" onclick="updateQuantity(${product.id}, -1)">-</button>
                    <span class="mx-2 fw-bold">${quantity}</span>
                    <button class="btn btn-sm btn-outline-secondary" onclick="updateQuantity(${product.id}, 1)">+</button>
                </div>
            `;
        } else {
            buttonHtml = `
                <button class="btn add-btn" onclick="addToCart(${product.id})">
                    Add to Cart
                </button>
            `;
        }

        productList.innerHTML += `
            <div class="col-md-3 mb-4">
                <div class="product-card">
                    <img src="${product.image}" class="product-img">
                    <h6 class="mt-2">${product.name}</h6>
                    
                    <div class="rating">
                        ${stars} <span class="rating-number">(${product.rating})</span>
                    </div>

                    <p class="price">₹${product.price}</p>

                    ${buttonHtml}
                </div>
            </div>
        `;
    });
}

/* ================= FILTER ================= */

function filterProducts(category) {
    currentCategory = category;
    displayProducts();
}

/* ================= ADD TO CART ================= */

function addToCart(id) {
    let item = cart.find(p => p.id === id);

    if (item) {
        item.quantity += 1;
    } else {
        const product = products.find(p => p.id === id);
        cart.push({ ...product, quantity: 1 });
    }

    saveCart();
    updateCartCount();
    if (document.getElementById("productList")) {
        displayProducts();
    }
}

/* ================= UPDATE CART COUNT ================= */

function updateCartCount() {
    const cartCount = document.getElementById("cartCount");
    if (!cartCount) return;

    const totalItems = cart.reduce((sum, item) => sum + item.quantity, 0);
    cartCount.innerText = totalItems;
}

/* ================= SAVE CART ================= */

function saveCart() {
    localStorage.setItem("cart", JSON.stringify(cart));
}

/* ================= DISPLAY CART ================= */

function displayCart() {
    const cartItemsDiv = document.getElementById("cartItems");
    const cartTotalSpan = document.getElementById("cartTotal");
    if (!cartItemsDiv || !cartTotalSpan) return;

    cartItemsDiv.innerHTML = "";
    if (cart.length === 0) {
        cartItemsDiv.innerHTML = '<div class="alert alert-info" role="alert">Your cart is empty. <a href="index.html">Continue shopping</a></div>';
        cartTotalSpan.innerText = "0";
        return;
    }

    let total = 0;
    const table = document.createElement("table");
    table.className = "table table-striped table-responsive";
    table.innerHTML = `
        <thead>
            <tr>
                <th scope="col">Product</th>
                <th scope="col">Price</th>
                <th scope="col">Quantity</th>
                <th scope="col">Subtotal</th>
                <th scope="col">Action</th>
            </tr>
        </thead>
        <tbody id="cartTableBody"></tbody>
    `;
    cartItemsDiv.appendChild(table);

    const tbody = document.getElementById("cartTableBody");
    cart.forEach(item => {
        const product = products.find(p => p.id === item.id);
        if (!product) return;

        const itemTotal = product.price * item.quantity;
        total += itemTotal;

        const row = document.createElement("tr");
        row.innerHTML = `
            <td>
                <div class="d-flex align-items-center">
                    <img src="${product.image}" alt="${product.name}" class="me-3" style="width: 60px; height: 60px; object-fit: cover; border-radius: 5px;">
                    <span>${product.name}</span>
                </div>
            </td>
            <td>₹${product.price}</td>
            <td>
                <div class="d-flex align-items-center">
                    <button class="btn btn-sm btn-outline-secondary" onclick="updateQuantity(${item.id}, -1)">-</button>
                    <input type="number" value="${item.quantity}" min="1" class="form-control mx-2 text-center" style="width: 60px;" onchange="updateQuantity(${item.id}, 0, this.value)">
                    <button class="btn btn-sm btn-outline-secondary" onclick="updateQuantity(${item.id}, 1)">+</button>
                </div>
            </td>
            <td><strong>₹${itemTotal}</strong></td>
            <td>
                <button class="btn btn-danger btn-sm" onclick="removeFromCart(${item.id})">Remove</button>
            </td>
        `;
        tbody.appendChild(row);
    });
    cartTotalSpan.innerText = total;
}

/* ================= REMOVE FROM CART ================= */

function removeFromCart(id) {
    cart = cart.filter(item => item.id !== id);
    saveCart();
    updateCartCount();
    if (document.getElementById("productList")) {
        displayProducts();
    }
    if (document.getElementById("cartItems")) {
        displayCart();
    }
}

/* ================= UPDATE QUANTITY ================= */

function updateQuantity(id, change, newValue = null) {
    const item = cart.find(item => item.id === id);
    if (!item) return;

    if (newValue !== null) {
        item.quantity = parseInt(newValue) || 0;
    } else {
        item.quantity += change;
    }

    if (item.quantity <= 0) {
        removeFromCart(id);
    } else {
        saveCart();
        updateCartCount();
        if (document.getElementById("productList")) {
            displayProducts();
        }
        if (document.getElementById("cartItems")) {
            displayCart();
        }
    }
}

/* ================= CHECKOUT ================= */

function checkout() {
    if (cart.length === 0) {
        alert("Your cart is empty!");
        return;
    }
    const total = cart.reduce((sum, item) => {
        const product = products.find(p => p.id === item.id);
        return sum + (product ? product.price * item.quantity : 0);
    }, 0);
    alert(`Thank you for shopping! Your total is ₹${total}. Your cart has been cleared.`);
    cart = [];
    saveCart();
    updateCartCount();
    displayCart();
}

/* ================= SEARCH LISTENER ================= */

const searchInput = document.getElementById("searchInput");
if (searchInput) {
    searchInput.addEventListener("keyup", displayProducts);
}

/* ================= INITIAL LOAD ================= */

displayProducts();
updateCartCount();
if (document.getElementById("cartItems")) {
    displayCart();
}
